  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Wraps aux pois chiches rôtis et à la feta', 'url', 'https://ici.radio-canada.ca/mordu/recettes/7796/wraps-pois-chiches-rotis-feta', 'storage:recipe-images/wraps-aux-pois-chiches-rotis-et-a-la-feta.webp', 4, 27, '["Dans une grande poêle antiadhésive à feu moyen-élevé, faites cuire les pois chiches et l’oignon dans l’huile jusqu’à ce qu’ils soient bien dorés, environ 12 minutes. Salez et poivrez. Ajoutez de l’huile au besoin. Retirez du feu et laissez tiédir.","Entre-temps, dans un bol, mélangez la crème sure, la feta, la menthe, le zeste de citron, l’ail et la tomate. Salez légèrement et poivrez. Ajoutez les pois chiches et mélangez bien. Rectifiez l’assaisonnement.","Sur un plan de travail, étalez les tortillas. Répartissez les feuilles de laitue et le mélange de pois chiches. Repliez les tortillas sur les garnitures de chaque côté, puis roulez-les fermement en emprisonnant les garnitures.","Accompagnez de crudités ou de salade verte, si désiré."]'::jsonb, 'wrap', 'pois chiches', array['printemps', 'ete']::text[]) returning id into r;
