  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Tofu Magique Bang Bang', 'url', 'https://www.loouniecuisine.com/fr/recettes/plats-principaux/tofu-magique-bang-bang/', 'storage:recipe-images/tofu-magique-bang-bang.webp', 4, null, '["Préchauffer le four à 375°. Couvrir une plaque de papier parchemin ou d’un tapis de cuisson anti-adhésif.","Préparation du tofu","Avec les doigts, défaire le tofu épongé en morceaux de la grosseur d’une bouchée. Ajouter la fécule de maïs et brasser doucement avec les mains pour bien enrober chaque morceau. Réserver.","Préparation de la sauce","Dans un petit bol, mettre la végénaise, la pâte de chili Sambal Oelek, la sauce soya, le jus de citron et le sirop d’érable. Mélanger jusqu’à l’obtention d’une texture homogène.","Préparation de l’appareil liquide","Prélever 3 c. à soupe de la sauce et la transférer dans un autre bol. Ajouter 3 c. à soupe d’eau, et mélanger jusqu’à l’obtention d’une texture homogène. Cette sauce diluée servira d’appareil liquide pour faire adhérer la chapelure.Pendant ce temps, mettre le restant de sauce à base de végénaise au réfrigérateur.","Préparation de la chapelure","Dans un bol, mettre la chapelure panko, la levure alimentaire et la poudre d’ail. Mélanger.","Assemblage","Préparer une station de travail avec le bol de sauce diluée et celui de mélange de chapelure.En procédant un morceau à la fois, tremper les morceaux de tofu dans la sauce diluée, et ensuite dans la préparation de chapelure. Disposer sur la plaque.Si on le souhaite, on peut ajouter un filet d’huile ou utiliser un vaporisateur d’huile sur les morceaux de tofu panés (facultatif, mais donnera un tofu plus croustillant!).","Cuisson","Enfourner 30 à 35 minutes, ou jusqu’à ce que les morceaux soient bien dorés (il est possible de les tourner à mi-cuisson, mais ce n’est pas nécessaire).","Présentation","Sortir la sauce du réfrigérateur.Servir avec la sauce en garniture ou en trempette. Décorer avec des oignons verts hachés.Avec un accompagnement de légumes verts (ici, j’ai fait cuire à la poêle des moitiés de bok choy avec un peu de sauce soya et de sirop d’érable, tout simplement!), on a un repas!"]'::jsonb, 'bol', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
