  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'One Pot Marry Me Tofu Recipe', 'url', 'https://makeitdairyfree.com/one-pot-marry-me-tofu/', 'storage:recipe-images/one-pot-marry-me-tofu-recipe.webp', 4, 45, '["For the tofu: Dry off any excess water from your tofu blocks with a towel gently. Using a knife, round the edges of your tofu block and cut in half to form two “tofu cutlets”. Repeat with second block of tofu. Add all your tofu seasonings to a small bowl and whisk together. Rub the spice mixture over both sides of the tofu. Set aside and allow to marinate for 10 minutes.","Once tofu is ready, add vegan butter to a large skillet over medium high heat. Once melted, add your tofu pieces and allow to sear for 2 minutes on each side. Remove tofu pieces to a plate and reduce heat to medium low.","Add more vegan butter or oil only if needed, and then add in the garlic, careful not to burn. Allow to cook for 1 minute. Add the spices and toast for 30 seconds or just until fragrant.","Add in the sun dried tomatoes and tomato paste and combine until a thick roux texture forms. Add stock, coconut milk, lemon juice, and wine. Stir together until well combined.","Add grated parmesan and stir together until cohesive and melted. Add spinach and all to cook for about a minute until wilted. Add tofu back into the skillet and cover with sauce. Allow to simmer for 20 minutes.","Serve over noodles, rice, gnocchi, or other side if desired."]'::jsonb, 'mijoté', 'tofu', array['automne', 'hiver']::text[]) returning id into r;
