  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Massaged Kale Salad', 'url', 'https://www.gazoakleychef.com/recipes/massaged-kale-salad/', 'storage:recipe-images/massaged-kale-salad.webp', 4, 15, '["Mix together vinegar, maple, mustard & oil in a small mixing bowl with the salt and chilli. Pour the dressing over the kale & massage everything together for 4-5 minutes with your hands.","Add the rest of the ingredients and stir well. Serve the salad right away with alfalfa spouts on top."]'::jsonb, 'salade', 'végé', array['printemps', 'ete']::text[]) returning id into r;
