  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Salade Thaï', 'url', 'https://www.lacuisinedejeanphilippe.com/recipe/salade-thai/', 'storage:recipe-images/salade-thai.webp', 2, null, '["Broyer les arachides et réserver.","Dans une poêle à frire, faire chauffer l’huile. Ajouter l’ail et le gingembre. Griller une ou deux minutes.","Ajouter la purée de piment, la sauce soja, le sirop d’érable, le vinaigre de riz et le beurre d’arachide. Bien mélanger.","Incorporer le lait de coco en brassant.","Retirer du feu et laisser refroidir.","Verser la sauce dans un saladier. Ajouter le reste des ingrédients et bien mélanger."]'::jsonb, 'salade', 'végé', array['printemps', 'ete']::text[]) returning id into r;
