  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Mac & cheese à la courge', 'url', 'https://cuisinez.telequebec.tv/recettes/940/mac-and-cheese-a-la-courge', 'storage:recipe-images/mac-cheese-a-la-courge.webp', 4, null, '["Cuire les pâtes dans une grande casserole d''eau bouillante selon les instructions de l''emballage. Égoutter.","Dans une casserole, chauffer le beurre et faire revenir les cubes de courge, l''oignon, l''ail, la moutarde et le piment de cayenne 2 à 3 minutes.","Verser le lait, porter à ébullition et laisser mijoter 15 à 20 minutes à feu doux.","Retirer du feu, ajouter le fromage et, à l''aide d''un pied-mélangeur, broyer le mélange afin d''obtenir une sauce lisse.","Ajouter les macaronis cuits et assaisonner.","Transférer le tout dans un plat à gratin et saupoudrer de chapelure.","Gratiner au four ou servir immédiatement."]'::jsonb, 'pâtes', 'fromage', array['automne', 'hiver']::text[]) returning id into r;
