  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Risotto à la courge butternut & sauge', 'url', 'https://dashofhoney.ca/fr/risotto-a-la-courge-butternut-sauge/', 'storage:recipe-images/risotto-a-la-courge-butternut-sauge.webp', 4, 55, '["Préchauffer le four à 400F et placer la grille au milieu du four. Déposer les cubes de courge sur une plaque à cuisson. Recouvrir les gousses d’ail à l’aide d’un papier d’aluminium (voir photo plus haut). Ajouter l’huile d’olive (3 c. à soupe) sur les morceaux de courge et l’ail. Bien assaisonner la courge et ajouter une pincée de cannelle. Bien incorporer. Cuire pendant 25-30 minutes en retournant à mi-cuisson.","Faire frire la sauge. Dans une poêle à feu moyen, ajouter l’huile d’olive. Dès que ça frémit, ajouter les feuilles de sauge et cuire environ 15 secondes. Retirer les feuilles et les déposer sur un papier essuie-tout. Réserver.","Préparer le risotto. Faire chauffer le bouillon de légumes dans un petit chaudron.","Dans une grande casserole, faire revenir les échalotes avec l’huile d’olive pendant 5 à 7 minutes. Assaisonner. Ajouter le riz et bien enrober. Déglacer avec le vin blanc. À feu moyen, ajouter le bouillon chaud graduellement : environ 1 tasse à la fois, en remuant fréquemment, puis s’assurer qu’il n’y ait plus de liquide dans la poêle. Répéter avec le reste du bouillon (4 à 5 fois). La cuisson prend environ 20 minutes. Si le riz est encore un peu dur, ajouter un peu d’eau pour obtenir une cuisson al dente.","Préparer la purée de courge. Déposer 2/3 des cubes* de courge rôties au robot culinaire avec l’ail rôti et ¼ tasse de bouillon de légumes. Pulser pour obtenir une purée lisse. Ajouter plus de bouillon au besoin en fonction de la consistance.","Ajouter la purée de courge au risotto cuit et bien incorporer. Retirer le risotto du feu et ajouter le parmesan et le beurre. Bien mélanger. Assaisonner.","Servir le risotto dans des bols/assiettes, garnir des morceaux de courge restants, feuilles de sauge et parmesan au goût."]'::jsonb, 'riz', 'végé', array['automne', 'hiver']::text[]) returning id into r;
