  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Protein-Packed Lentil & Quinoa Salad', 'url', 'https://www.pickuplimes.com/recipe/protein-packed-lentil-quinoa-salad-208', 'storage:recipe-images/protein-packed-lentil-quinoa-salad.webp', 4, 25, '["Cook the quinoa according to the package instructions.","Soak the edamame in hot water while working through the remaining steps.","Mix all of the dressing ingredients in a bowl until creamy.","Drain the edamame and add all of the salad ingredients to a large bowl and toss to combine.","Mix in the salad dressing when ready to serve, toss to combine, and enjoy!"]'::jsonb, 'salade', 'lentilles', array['printemps', 'ete']::text[]) returning id into r;
