  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Warm Pearl Couscous Salad', 'url', 'https://www.pickuplimes.com/recipe/warm-pearl-couscous-salad-542', 'storage:recipe-images/warm-pearl-couscous-salad.webp', 4, 25, '["Cook the couscous according to the package instructions, then drain.","Meanwhile, drizzle oil in a medium pan over medium-high heat. When hot, add the chickpeas, tomatoes, salt, and pepper. Cook for 5 to 7 minutes, stirring occasionally. Remove from the heat.","In a small bowl, mix together the ingredients for the dressing.","To a large bowl, add the drained couscous, tomato and chickpea mixture, cucumber slices, olives, and fresh herbs. Add the dressing, toss to combine, spinkle over the almonds, and enjoy!","The salad can be stored in an airtight container in the fridge separate from the dressing for up to 3 days.","Combine the dressing and salad when ready to enjoy."]'::jsonb, 'salade', 'pois chiches', array['printemps', 'ete']::text[]) returning id into r;
