  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Bol de tofu katsu', 'url', 'https://margauxfood.ca/recette/bol-de-tofu-katsu/', 'storage:recipe-images/bol-de-tofu-katsu.webp', 4, 45, '["Dans une poêle antiadhésive, chauffer l’huile à feu moyen et cuire l’oignon et la carotte pendant 7 minutes en brassant à quelques reprises. Ajouter l’ail, le gingembre, les graines de coriandre, la poudre de cari et le curcuma et cuire encore 3 minutes en brassant souvent.","Transférer le mélange d’oignon dans un mélangeur et ajouter les autres ingrédients de la sauce. Mélanger jusqu’à l’obtention d’une texture très lisse.","Dans la même poêle antiadhésive, déposer la sauce et porter à ébullition. Réduire le feu et laisser réduire pendant quelques minutes jusqu’à ce que la sauce ait épaissi.","Dans un bol, mélanger la farine, le lait, la fécule de maïs, la lime et le cari. Dans une assiette creuse, mélanger la chapelure et le sel.","Tremper les tranches de tofu dans le mélange liquide et égoutter légèrement. Enrober les tranches de tofu de chapelure en pressant bien.","Dans une poêle antiadhésive, chauffer l’huile à feu moyen-élevé et dorer les tranches de tofu environ 2 à 3 minutes par côté, ou jusqu’à ce qu’elles soient bien dorées.","Servir avec du riz, la sauce au cari et du basilic frais!"]'::jsonb, 'bol', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
  insert into recipe_ingredients (recipe_id, position, section, raw, quantity, quantity_max, unit, name, note, optional, ingredient_id) values (r, 0, 'Sauce au cari', '2 c. à soupe (30 ml) d’huile végétale', 2, null, 'tbsp', 'huile végétale', '30 ml', false, (select id from ingredients where household_id is null and name = 'Huile végétale'));
