  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Dhal de lentilles au curcuma et lait de coco avec pleurotes au paprika fumé', 'url', 'https://domcooks.com/recettes/dhal-de-lentilles-au-curcuma-et-lait-de-coco-pleurotes-au-paprika-fume', 'storage:recipe-images/dhal-de-lentilles-au-curcuma-et-lait-de-coco-avec-pleurotes-.webp', 4, 27, '["Chauffer une cocotte ou un chaudron à feu moyen élevé. Ajouter l’huile, l’oignon et la pomme et cuire environ 2 à 3 minutes. Remuer et ajouter l’ail et le gingembre – cuire une minute. Ajouter le curcuma, le garam masala et le paprika fumé, puis remuer et cuire jusqu’à ce que les épices commencent à sentir.","Ajouter les lentilles et le bouillon de légumes. Gratter le fond de la poêle et ajouter le lait de coco. Saler et poivrer, porter à ébullition et couvrir. Laisser mijoter à feu doux environ 15 minutes.","Pendant ce temps, préchauffer le four à 425 F.","Ajouter une feuille de papier parchemin sur une plaque allant au four. Placer les champignons par-dessus et ajouter les autres ingrédients. S’assurer de bien enrober tous les morceaux de champignons. Cuire au four environ 10 minutes. S’ils ne sont pas assez rôtis, mettre à broil lors des dernières minutes.","Vérifier si le dhal a atteint une texture crémeuse. Si la préparation est encore trop liquide, retirer le couvercle et cuire encore 3 à 5 minutes. Incorporer le zeste et le jus de lime à la dernière minute.","Servir immédiatement dans des bols et parsemer de champignons, d’oignons rouges, de piment jalapeno, d’un filet de lait de coco, de coriandre fraîche et plus de piment gochugaru, au goût!","Infos nutritionnelles par portion","Calories 360 kCal Protéines 13 g Glucides 35 g Lipides 22 g","Recettes de la même catégorie:","Braisé de boeuf à la harissa sur pappardelles aux oeufs","Pâtes au poulet, lardons et champignons avec sauce crémeuse à la moutarde","Dindon rôti à la moutarde et à la sauge avec farce au fenouil, au poireau et au thym","Et pour partager c''est par ici:"]'::jsonb, 'mijoté', 'lentilles', array['automne', 'hiver']::text[]) returning id into r;
