  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Patates douces farcies à la mexicaine', 'url', 'https://margauxfood.ca/recette/patates-douces-farcies-a-la-mexicaine/', 'storage:recipe-images/patates-douces-farcies-a-la-mexicaine.webp', 4, 50, '["Préchauffer le four à 400°F et placer la grille au centre. Tapisser une plaque à biscuits de papier parchemin.","Couper les patates douces en deux dans le sens de la longueur et parsemer d’huile et de sel. Déposer les patates douces sur la plaque, côté coupé vers le bas et cuire 30 à 35 minutes ou jusqu’à ce que la pointe d’un couteau s’insère facilement dans la chair des patates douces.","Dans un bol, mélanger tous les ingrédients de la salade de haricots noirs.","Dans une assiette creuse, écraser les avocats jusqu’à l’obtention d’une texture semi-lisse. Ajouter la lime et le sel et bien mélanger.","Déposer une moitié de patate douce dans une assiette. Étendre un peu de guacamole sur le dessus, ajouter de la salade de haricots et les garnitures, si désiré. Répéter pour toutes les moitiés de patates douces."]'::jsonb, 'four', 'haricots noirs', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
