  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Tofu Magique', 'url', 'https://www.loouniecuisine.com/fr/recettes/plats-principaux/tofu-magique/', 'storage:recipe-images/tofu-magique.webp', 4, null, '["Préparation des bouchées de tofu","Dans un bol, défaire le tofu avec les doigts en morceaux de la grosseur d’une bouchée (les morceaux n’ont pas besoin d’être parfaitement uniformes!).","Ajouter le vinaigre de cidre, la sauce soya et le sirop d’érable. Bien mélanger.","Ajouter la levure alimentaire. Bien mélanger pour enrober les morceaux.","Cuisson","Cuisson au four (un peu plus long, mais plus facile et parfait à tous coups!)","Préchauffer le four à 375°F (190°C). Sur une plaque couverte de papier parchemin ou d’un tapis de cuisson anti-adhésif, déposer les bouchées de tofu. Arroser d’un peu d’huile si on le souhaite (facultatif). Cuire 25 minutes, ou jusqu’à ce que les morceaux soient bien dorés.","Cuisson à la poêle (plus rapide, mais avec une plus grande marge d’erreur selon le type de tofu et de poêle)","Dans une poêle anti-adhésive à feu moyen-élevé, cuire les morceaux de tofu dans un peu d’huile, environ 8 minutes en remuant régulièrement, jusqu’à ce qu’ils soient bien dorés."]'::jsonb, 'bol', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
  insert into recipe_ingredients (recipe_id, position, section, raw, quantity, quantity_max, unit, name, note, optional, ingredient_id) values (r, 0, null, '1 bloc de 450-454 g de tofu extra-ferme, épongé dans un linge sec', 1, null, 'block', 'tofu extra-ferme', 'épongé dans un linge sec; 450-454 g', false, (select id from ingredients where household_id is null and name = 'Tofu extra-ferme'));
