  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Salade de légumineuses au maïs grillé et à la pomme', 'url', 'https://ici.radio-canada.ca/mordu/recettes/9818/salade-legumineuses-mais-pomme', 'storage:recipe-images/salade-de-legumineuses-au-mais-grille-et-a-la-pomme.webp', 4, 20, '["Dans une poêle à feu moyen élevé, faites chauffer l’huile. Ajoutez les grains de maïs et faites-les sauter de 4 à 5 minutes, ou jusqu’à ce que les grains aient une belle coloration. Réservez-les sur une plaque ou dans une assiette pour les laisser tempérer.","Dans un saladier, mélangez l’oignon rouge haché et les dés de pomme. Ajoutez le vinaigre de vin, la moutarde à l’ancienne et le sel. Mélangez bien et laissez reposer le tout le temps de préparer le reste des ingrédients.","Dans un bol, mettez les pois chiches. À l’aide d’une fourchette ou avec les mains, écrasez les pois chiches afin d’obtenir une texture de hachis grossier. Transférez les pois chiches écrasés dans le saladier.","Ajoutez les grains de maïs grillés, les haricots blancs, le céleri, le persil, la mayonnaise végétalienne, la poudre d’ail, le paprika doux et le paprika fumé. Mélangez bien la salade.","Ajoutez de la sauce piquante au goût et rectifiez l’assaisonnement."]'::jsonb, 'salade', 'pois chiches', array['ete', 'automne']::text[]) returning id into r;
