  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Feta au four à l''indienne', 'url', 'https://www.folksandforks.ca/recettes/feta-au-four-a-lindienne', 'storage:recipe-images/feta-au-four-a-l-indienne.webp', 4, null, '["Préchauffer le four à 400 F.","Dans une poêle à feu doux, faire suer l''ail, l''oignon et le gingembre dans le beurre.","Ajouter un peu d’huile d’olive, les épices, la pâte de tomate et les pois chiches, puis poursuivre la cuisson pendant environ 1 minute en remuant.","Incorporer le lait de coco, mélanger et laisser réduire la sauce pendant 5 minutes.","Goûter la sauce et rectifier l''assaisonnement (peut-être avec un peu de sel ou de poudre de chili si vous préférez que ce soit plus épicé).","Ajouter les morceaux de feta et envoyer au four. Cuire pendant 15 à 20 minutes ou jusqu''à ce que la feta soit bien cuite (il ne fondra pas, il gardera sa texture ferme). Retourner la feta à mi-cuisson.","Lorsque c''est prêt, servir immédiatement sur un lit de riz basmati et des naan ou simplement à même la poêle avec des pains naan en mode pique-assiette.","Parsemer de persil frais ou de coriandre fraîche finement hachée."]'::jsonb, 'four', 'fromage', array['automne', 'hiver']::text[]) returning id into r;
