  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Bean Crispy Salad', 'manual', 'https://www.pickuplimes.com/recipe/three-bean-crispy-rice-salad-1691', 'storage:recipe-images/bean-crispy-salad.webp', 3, null, '["Cook the rice according to the package instructions. Then spread it out on a large tray and let it cool off.","Add oil to a large pan and heat over medium-high.","Press rice into a flat layer on the pan and cook for about 15 - 20 minutes, or until golden and crispy to your liking. Toss once or twice while cooking.","Meanwhile, mix the dressing ingredients together in a small bowl. Set aside.","Add the beans and parsley to a large bowl.","Break the rice into bite-sized clumps and add them to the bowl. When ready to enjoy, pour over the dressing and toss to coat. Enjoy!"]'::jsonb, 'salade', 'haricots rouges', array['printemps', 'ete']::text[]) returning id into r;
