  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Tofu croustillant sésame et érable', 'manual', null, 'storage:recipe-images/tofu-croustillant-sesame-et-erable.webp', 4, null, '["Avec les doigts, défaire le tofu en morceaux de la grosseur d’une petite bouchée et mettre dans un bol. Ajouter la fécule de maïs, le sel, et bien mélanger.","Dans une poêle antiadhésive, à feu moyen-élevé, chauffer l’huile. Ajouter le tofu et faire sauter durant 5 min en brassant régulièrement, jusqu’à ce que les petits morceaux de tofu soient bien colorés.","Dans un petit bol, mettre la sauce soya, le sirop d''érable, l’huile de sésame grillé et le vinaigre de riz, puis mélanger.","Verser la sauce sur le tofu et mélanger afin de bien enrober tous les morceaux. Ajouter les graines de sésame grillées, bien mélanger et réserver au chaud."]'::jsonb, 'bol', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
