  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Mapo Tofu Udon', 'manual', null, 'storage:recipe-images/mapo-tofu-udon.webp', 4, null, '["Cook udon according to package directions. Drain and toss with a little sesame oil to keep from sticking. Set aside.","Blend the creamy sauce.","Heat a splash of oil in a skillet over medium-high heat.","Add the crumbled tofu with the cornstarch until golden.","Add garlic and ginger; cook until fragrant.","Add the rest of the ingredients and cook until golden and crispy.","Serve.","Place cooked udon in bowls.","Spoon creamy tofu sauce over the noodles and add the tofu crumbles.","Garnish with green onion and sesame seeds."]'::jsonb, 'nouilles', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
