  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Creamy Roasted Cauliflower Ramen', 'manual', null, 'storage:recipe-images/creamy-roasted-cauliflower-ramen.webp', 3, null, '["Preheat oven to 390 °F.","Line a large baking tray.","Prep : Slice the cauliflower into florets. Dice the garlic and ginger. Slice the spring onions (if using for garnish).","Roast the Cauliflower : Spread cauliflower florets on the baking tray. Drizzle or spray with olive oil and add a pinch of salt. Roast for 20 minutes, until golden and crispy. Set aside some cauliflower for garnish.","Make the Creamy Broth : Add the remaining roasted cauliflower to a blender. Add: Silken tofu. White miso paste. Soy sauce. Coconut milk. Vegetable stock. Blend until completely smooth.","Cook the Broth : Heat a drizzle of oil in a saucepan. Fry the garlic and ginger for 2 minutes. Pour in the blended broth. Bring to a gentle simmer. Add a splash of water if needed to loosen.","Cook the Noodles : Cook ramen noodles according to packet instructions. Drain.","Assemble : Divide noodles between bowls. Ladle over the creamy broth. Top with crispy roasted cauliflower. Finish with chilli oil and fresh coriander. On a ajouté des œufs mollets et des feuilles de nori."]'::jsonb, 'ramen', 'tofu', array['automne', 'hiver']::text[]) returning id into r;
