  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Creamy Peanut Ramen with Enoki, Bok Choy & Egg', 'manual', null, 'storage:recipe-images/creamy-peanut-ramen-with-enoki-bok-choy-egg.webp', 4, null, '["Boil you eggs for 6-7 min and immediately transfer them to an ice bath for 5 min. Peel and set aside.","Heat olive oil in a medium stock pot over medium-high heat.","Add enoki mushrooms and the bok choy and cook until golden. Set aside.","Add olive oil, garlic and ginger; sauté 30 seconds until fragrant.","Add crumbled tofu and sauté 5–7 minutes, lightly golden.","Stir in peanut butter until everything is coated.","Pour in vegetable stock and bring to a gentle boil.","Add soy sauce, rice vinegar, sesame oil, and cane sugar. Stir well.","Simmer for 5 minutes.","Cook ramen noodles separately according to package directions.","Divide noodles between bowls and ladle broth, tofu, and vegetables over top.","Finish with soft-boiled eggs, nori, peanuts, green onion, cilantro, chili oil, and sesame seeds."]'::jsonb, 'ramen', 'tofu', array['automne', 'hiver']::text[]) returning id into r;
