  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Nouilles udon au tofu croustillant', 'url', 'https://margauxfood.ca/recette/nouilles-udon-au-tofu-croustillant/', 'storage:recipe-images/nouilles-udon-au-tofu-croustillant.webp', 4, 25, '["Dans une petite casserole, chauffer l’huile de sésame à feu moyen élevé et cuire les gousses d’ail 2 minutes en brassant souvent. Ajouter le reste des ingrédients de la sauce et laisser réduire environ 3 minutes.","Dans un bol, mélanger le tofu, la fécule de maïs et le sel.","Dans une poêle antiadhésive, chauffer l’huile à feu moyen-élevé et cuire le tofu pendant 5 à 6 minutes en brassant souvent, ou jusqu’à ce qu’il soit bien doré.","Dans une casserole d’eau bouillante salée, cuire les nouilles selon le temps de cuisson indiqué sur l’emballage. Égoutter.","Ajouter la sauce, les nouilles, le basilic et les oignons verts dans la poêle et mélanger délicatement jusqu’à ce que les nouilles soient bien enrobées de sauce. Servir avec les garnitures."]'::jsonb, 'nouilles', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
