  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Salade de légumes grillés aux lentilles, vinaigrette tahini, Dijon et érable', 'url', 'https://margauxfood.ca/recette/salade-de-legumes-grilles-aux-lentilles/', 'storage:recipe-images/salade-de-legumes-grilles-aux-lentilles-vinaigrette-tahini-d.webp', 4, 45, '["Préchauffer le four à 425°F et placer la grille au centre. Tapisser une grande plaque à biscuits de papier parchemin.","Déposer tous les ingrédients des légumes grillés dans la plaque et mélanger à l’aide des mains ou d’une cuillère jusqu’à ce que les légumes soient bien enrobés d’huile et d’épices. Cuire au four 25 à 30 minutes. Laisser refroidir une dizaine de minutes.","Dans un bol, à l’aide d’un fouet, mélanger tous les ingrédients de la vinaigrette.","Dans un grand bol à salade, mélanger délicatement tous les ingrédients de la salade avec les légumes grillés et la vinaigrette. Déguster!!","Il est important de ne pas trop cuire les légumes pour éviter qu’ils s’écrasent dans la salade."]'::jsonb, 'salade', 'lentilles', array['automne', 'hiver']::text[]) returning id into r;
