  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Ragoût crémeux express à la citrouille', 'photo', null, 'storage:recipe-images/ragout-cremeux-express-a-la-citrouille.webp', 4, null, '["Dans un chaudron à feu moyen-élevé, chauffer l''huile. Ajouter l''oignon et faire sauter 3 minutes. Ajouter la pâte de tomate, la pâte de miso et la moutarde de Dijon, et bien mélanger.","Ajouter l''ail, les carottes, le céleri et les courgettes, et mélanger. Cuire 5 minutes en brassant régulièrement.","Ajouter la purée de citrouille, les tomates, les haricots, l''eau et les herbes italiennes. Porter à ébullition, puis réduire à feu moyen et laisser mijoter à découvert 10 minutes ou jusqu''à ce que le ragoût soit bien chaud.","Goûter, puis saler, au goût.","Répartir le ragoût dans des bols peu profonds. Garnir du tahini, de flocons de piment fort, de grenoblata ou de persil plat, au goût.","Servir avec un bon pain croûté !"]'::jsonb, 'mijoté', 'haricots blancs', array['automne']::text[]) returning id into r;
