  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Pâté samosa', 'photo', null, 'storage:recipe-images/pate-samosa.webp', 4, null, '["Préchauffer le four à 375 °F (190 °C).","Déposer les carottes et les pommes de terre dans une casserole. Ajouter assez d''eau pour couvrir les légumes.","Porter à ébullition. Réduire le feu et laisser mijoter 15 minutes ou jusqu''à ce que les légumes soient partiellement cuits. Égoutter et réserver.","Dans une grande poêle, à feu moyen-vif, faire revenir l''oignon et les champignons dans l''huile 5 minutes. Ajouter le reste des ingrédients (sauf la pâte à tarte !) ainsi que les carottes et les pommes de terre précuites.","Abaisser la pâte à tarte pour former deux cercles de ½ cm (¼ po) d''épaisseur.","Foncer une assiette à tarte de 9 po (23 cm) avec une abaisse de pâte. Y répartir le mélange. Couvrir d''une deuxième abaisse. Faire une incision au centre. Bien sceller en écrasant le rebord à l''aide d''une fourchette ou avec les doigts.","Cuire au four de 50 minutes à 1 heure, ou jusqu''à ce que la croûte soit bien dorée."]'::jsonb, 'four', 'pois chiches', array['automne', 'hiver']::text[]) returning id into r;
