  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Soupe de lentilles épicée à l''oignon brûlé', 'photo', null, 'storage:recipe-images/soupe-de-lentilles-epicee-a-l-oignon-brule.webp', 4, null, '["Dans un chaudron à feu moyen-élevé, déposer les tranches d''oignon. Cuire à sec environ 8 minutes ou jusqu''à l''obtention d''une coloration intense.","Verser l''eau et cuire encore 2 minutes pour décoller les oignons en raclant bien le fond du chaudron.","Verser cette préparation dans un bol et réserver.","Dans le même chaudron à feu moyen-élevé, chauffer l''huile. Ajouter les graines de cumin et faire rôtir 2 minutes ou jusqu''à ce qu''elles soient bien dorées et odorantes.","Ajouter les ingrédients ci-contre dans le chaudron et cuire 3 minutes."]'::jsonb, 'soupe', 'lentilles', array['automne', 'hiver']::text[]) returning id into r;
