  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Vegan Jamaican Lentil Curry', 'photo', null, 'storage:recipe-images/vegan-jamaican-lentil-curry.webp', 4, null, '["In a large saucepan, heat oil over medium high. Once hot, add onions and peppers and cook until soft, about 3-4 minutes. Add in garlic, green onions, ginger, and thyme, and cook until fragrant, about 2 minutes. Add curry powder, bouillon, garam masala, cumin, paprika, and allspice. Stir together and cook for 1 minute.","Add lentils, potatoes, and carrots. Stir together. Add the broth and combine. Bring to a boil, add the scotch bonnet pepper, then reduce heat to low. Cover and cook on simmer for 15-20 minutes. Lentils should be soft and vegetables tender.","Add spinach, coconut milk, and peanut butter, if adding. Stir together well. Let cook for 5 minutes, spinach should be wilted. If your curry feels too thick, add additional broth to thin. Remove from the heat.","Remove pepper and thyme sprigs. Stir in lime juice as desired. Serve with Jamaican rice and peas."]'::jsonb, 'mijoté', 'lentilles', array['automne', 'hiver']::text[]) returning id into r;
