  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Salade de nouilles orientales au tempeh caramélisé', 'photo', null, 'storage:recipe-images/salade-de-nouilles-orientales-au-tempeh-caramelise.webp', 4, null, '["Porter une grande casserole d''eau à ébullition. Cuire les nouilles selon les indications sur l''emballage. Égoutter et réserver dans un grand plat de service.","Couper le tempeh et l''aubergine en cubes.","Dans un grand poêlon antiadhésif, chauffer l''huile d''olive à feu vif. Cuire le tempeh et l''aubergine 10 minutes en remuant à quelques reprises, jusqu''à ce que le tempeh soit bien doré. Poivrer généreusement et ajouter une pincée de sel.","Dans un petit bol, mélanger 60 ml (1/4 tasse) de sirop d''érable, le vinaigre balsamique et 30 ml (2 c. à soupe) de sauce soya. Verser la sauce sur le tempeh et les aubergines. Poursuivre la cuisson 5 minutes. Déposer sur les nouilles.","Hacher grossièrement les épinards. Déposer sur la salade.","À l''aide d''une râpe fine (de type Microplane), sans le peler, râper le gingembre. Hacher finement l''ail. Déposer dans le bol utilisé pour faire la sauce.","Directement au-dessus du bol, presser les limes. Ajouter le reste du sirop d''érable (15 ml / 1 c. à soupe), le reste de la sauce soya (15 ml / 1 c. à soupe), l''huile de sésame et les flocons de piment fort. Bien mélanger.","Verser la vinaigrette sur la salade, mélanger et servir."]'::jsonb, 'salade', 'tempeh', array['printemps', 'ete']::text[]) returning id into r;
