  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Bol quinoa, tofu et arachides', 'photo', null, 'storage:recipe-images/bol-quinoa-tofu-et-arachides.webp', 1, null, '["Dans une casserole, porter à ébullition le quinoa et le bouillon de poulet. Dès les premiers bouillons, couvrir et diminuer le feu à feu minimum. Cuire de 12 à 15 minutes. Retirer du feu. Ajouter le gingembre, la coriandre, l''oignon vert et l''huile de sésame. Mélanger. Remettre le couvercle. Réserver.","Dans un bol, mélanger les ingrédients de la sauce. Chauffer 30 secondes au micro-ondes. Réserver.","Dans une poêle antiadhésive, chauffer l''huile à feu vif. Saisir les cubes de tofu. Assaisonner de sel et de poivre. Cuire 2-3 minutes. Ajouter l''oignon. Cuire 2-3 minutes ou jusqu''à légère coloration. Ajouter les arachides. Cuire 1 minute à feu vif. Retirer du feu.","Dans un autre bol, mettre le quinoa. Ajouter le tofu aux arachides.","Garnir de chou rouge, de carotte, de concombre, de radis et d''oignon vert.","Arroser de sauce et accompagner d''un quartier de lime."]'::jsonb, 'bol', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
