  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Sauté de tofu, oignons verts et sésame style philippino', 'photo', null, 'storage:recipe-images/saute-de-tofu-oignons-verts-et-sesame-style-philippino.webp', 4, null, '["Dans un bol, mélanger tous les ingrédients de la sauce. Réserver.","Dans une grande poêle antiadhésive, chauffer l''huile. Saisir les cubes de tofu 2-3 minutes de tous les côtés jusqu''à obtenir une belle coloration.","Ajouter l''oignon, l''ail et le gingembre et cuire 1 minute.","Ajouter le poivron, le piment, les champignons et les oignons verts. Cuire 2-3 minutes jusqu''à obtenir une légère coloration.","Incorporer la sauce. Cuire 1 minute.","Retirer du feu. Ajouter les graines de sésame et la mayonnaise. Mélanger.","Servir dans un bol et garnir de graines de sésame et d''arachides au goût. Accompagner d''un féculent."]'::jsonb, 'bol', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
