  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Pâtes crémeuses au maïs et chorizo de tofu', 'url', 'https://margauxfood.ca/recette/pates-cremeuses-au-mais-et-chorizo-de-tofu/', 'storage:recipe-images/pates-cremeuses-au-mais-et-chorizo-de-tofu.webp', 4, 40, '["Dans une grande poêle antiadhésive, chauffer l’huile à feu moyen-élevé et émietter le tofu en petits morceaux avec les mains. Ajouter le reste des ingrédients sauf la pâte de tomate et cuire pendant 4 minutes en brassant à quelques reprises.","Ajouter la pâte de tomates et bien brasser. Poursuivre la cuisson 2 minutes. Transférer le chorizo de tofu dans une assiette.","Dans la même poêle antiadhésive, chauffer l’huile à feu moyen-élevé et cuire l’oignon pendant 5 minutes. Ajouter les grains de maïs, l’ail et les flocons de piment fort et cuire encore 4 minutes.","Transférer la moitié du mélange d’oignon et de maïs dans un mélangeur avec la crème végétale, le bouillon, le sel et le poivre et mixer jusqu’à l’obtention d’une texture très lisse.","Dans une casserole d’eau bouillante salée, cuire les pâtes selon le temps indiqué sur l’emballage. Prélever 1/3 tasse (80 ml) d’eau de cuisson et égoutter les pâtes.","Déposer les pâtes et l’eau de cuisson dans la poêle avec le reste du mélange d’oignon et de maïs, la sauce et le basilic. Servir avec le chorizo de tofu."]'::jsonb, 'pâtes', 'tofu', array['ete', 'automne']::text[]) returning id into r;
