  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Salade de quinoa et halloumi sur crème d''avocat', 'photo', null, 'storage:recipe-images/salade-de-quinoa-et-halloumi-sur-creme-d-avocat.webp', 4, null, '["Dans une grande poêle à feu moyen, faire dorer les cubes de fromage 2-3 minutes de chaque côté. Réserver dans une assiette et laisser refroidir complètement.","Préparer la vinaigrette en mélangeant tous les ingrédients ensemble dans un petit bol.","Préparer la crème d''avocat. Ajouter tous les ingrédients dans un robot culinaire et pulser pendant 1-2 minutes, jusqu''à l''obtention d''une texture crémeuse. Réserver.","Dans un grand bol, mélanger les ingrédients pour la salade avec les cubes de fromage refroidis. Verser la vinaigrette sur la salade et bien mélanger. Rectifier l''assaisonnement au besoin.","Pour servir, étendre la crème d''avocat dans une assiette de service (ou dans 4 assiettes creuses) et déposer la salade par-dessus. Garnir de chips de pita, de graines de grenade supplémentaires et saupoudrer d''un peu de sumac."]'::jsonb, 'salade', 'fromage', array['printemps', 'ete']::text[]) returning id into r;
