  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Pain plat d''été au tofu crémeux façon burrata', 'photo', null, 'storage:recipe-images/pain-plat-d-ete-au-tofu-cremeux-facon-burrata.webp', 4, null, '["Épongez le tofu pour retirer l''excédent d''eau, mais sans trop le presser. Émiettez-le avec les mains et mettez-le dans un bol.","Ajoutez la crème de soya et mélangez le tout. Salez au goût. Réservez le tofu au frais.","Dans un petit bol, mélangez le sirop et les flocons de piment.","Avec les mains, humectez les pains plats avec de l''eau pour leur permettre de garder une texture plus souple à la cuisson.","Badigeonnez les pains avec un peu d''huile de chaque côté. Badigeonnez aussi les tranches de pêches.","Sur le barbecue ou sur une poêle striée, à feu moyen-élevé, faites griller les pains environ 2 minutes de chaque côté, ou jusqu''à ce qu''ils soient chauds et que des marques du gril soient visibles. Réservez-les.","Faites griller les tranches de pêches 2 minutes d''un côté, puis 1 minute de l''autre. Réservez-les.","Salez légèrement les tranches de tomates pour leur permettre de recracher une partie de leur eau. Réservez-les.","Tartinez les pains avec le pesto. Garnissez-les de tranches de tomates, de tranches de pêche grillées et de tofu crémeux.","Ajoutez la roquette et les feuilles de basilic. Terminez le dressage par un filet de sirop épicé et servez les pains plats garnis immédiatement."]'::jsonb, 'pain plat', 'tofu', array['ete']::text[]) returning id into r;
