  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Aubergines grillées et pois chiches au cari', 'photo', null, 'storage:recipe-images/aubergines-grillees-et-pois-chiches-au-cari.webp', 4, null, '["Préchauffer le barbecue à puissance élevée. Huiler un côté de la grille.","Déposer les quartiers d''aubergines sur une plaque de cuisson.","Dans un bol, mélanger au fouet l''huile et le cari. Prélever 125 ml (1/2 tasse) de l''huile. À l''aide d''un pinceau, badigeonner les aubergines. Réserver.","Dans le bol avec le reste de l''huile, ajouter les pois chiches, les raisins secs, l''ail, le gingembre et le piment. Saler, poivrer et bien mélanger. Répartir le mélange de pois chiches sur une grande feuille de papier d''aluminium et refermer la papillote hermétiquement.","Déposer la papillote sur le côté non huilé de la grille. Fermer le couvercle et cuire 12 minutes ou jusqu''à ce que les pois chiches soient légèrement rôtis, en retournant la papillote à quelques reprises durant la cuisson. En même temps, griller les aubergines sur le côté huilé de la grille 4 minutes de chaque côté.","Ouvrir la papillote et déposer le mélange de pois chiches dans un bol. Ajouter les tomates et bien mélanger. Rectifier l''assaisonnement.","Sur une grande assiette de service, étaler le yogourt. Répartir les aubergines et le mélange de pois chiches. Parsemer de feuilles de menthe. Accompagner de pains naans."]'::jsonb, 'mijoté', 'pois chiches', array['ete', 'automne']::text[]) returning id into r;
