  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Tofu magique général Tao sur le BBQ', 'photo', null, 'storage:recipe-images/tofu-magique-general-tao-sur-le-bbq.webp', 4, null, '["Pressez le tofu pour retirer l''excédent d''eau.","Coupez le tofu en 8 tranches d''environ 1 cm (⅜ po) d''épaisseur. Réservez.","Dans un contenant hermétique, versez la sauce soya, le sirop d''érable, le vinaigre de riz, la levure alimentaire et l''huile. Mélangez bien.","Ajoutez les tranches de tofu dans la marinade en prenant soin de bien couvrir chaque côté. Laissez mariner au réfrigérateur au moins 30 minutes, ou encore plusieurs heures.","Mettez tous les ingrédients dans un bol. Mélangez la sauce et réservez-la.","Préchauffez le barbecue à 200 °C (400 °F) et huilez bien les grilles.","Déposez les tranches de tofu marinées sur les grilles, en prenant soin d''y ajouter la marinade restante. Faites cuire les tranches 3 minutes d''un côté, puis tournez-les.","Badigeonnez généreusement le dessus des tranches avec environ le tiers de la sauce. Laissez-les cuire 3 minutes.","Tournez à nouveau les tranches de tofu, et badigeonnez-les d''un autre tiers de la sauce. Laissez-les cuire 3 minutes.","Tournez une troisième fois les tranches et badigeonnez-les avec le restant de la sauce.","Fermez le couvercle et laissez-les cuire 3 minutes, ou jusqu''à ce que la sauce soit légèrement caramélisée et collante.","Retirez le tofu du feu et garnissez-le avec des graines de sésame et des oignons verts hachés, si désiré."]'::jsonb, 'grillades', 'tofu', array['ete']::text[]) returning id into r;
