  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Tofu grillé aux olives et à l''aneth', 'photo', null, 'storage:recipe-images/tofu-grille-aux-olives-et-a-l-aneth.webp', 4, null, '["Pressez le tofu pour en retirer l''excédent d''eau.","Coupez le tofu en huit tranches d''environ 1 cm (⅜ po) d''épaisseur. Mettez-les dans un contenant hermétique et réservez-les.","Mettez le reste des ingrédients dans le bol d''un mélangeur et broyez le tout jusqu''à l''obtention d''une texture lisse.","Versez la marinade sur les tranches de tofu, en prenant soin d''en badigeonner tous les côtés. Couvrez le tofu et laissez-le mariner au réfrigérateur au moins 30 minutes, pendant quelques heures ou jusqu''à une nuit entière.","Préchauffez le barbecue à 200 °C (400 °F) et huilez bien les grilles.","Déposez les tranches de tofu mariné sur les grilles, en les badigeonnant d''un peu de marinade. Faites-les cuire 4 minutes, puis retournez-les.","Badigeonnez de nouveau les tranches et laissez-les cuire 4 minutes.","Retournez les tranches une dernière fois, fermez le couvercle du barbecue et laissez cuire le tofu de 2 à 3 minutes.","Retirez les tranches de tofu du feu. Arrosez-les du reste de la marinade, si désiré, ou d''un filet d''huile d''olive."]'::jsonb, 'grillades', 'tofu', array['ete']::text[]) returning id into r;
