  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Salade de pâtes aux légumes rôtis et chèvre', 'photo', null, 'storage:recipe-images/salade-de-pates-aux-legumes-rotis-et-chevre.webp', 4, null, '["Préchauffer le four à 425 °F et placer la grille au milieu.","Sur une grande plaque à cuisson avec un papier parchemin, ajouter les dés d''aubergine, de poivron rouge, de courgette et d''oignon rouge. Saupoudrer d''herbes de Provence. Ajouter 1 c. à thé de sel et 2 c. à soupe d''huile d''olive. Bien répartir sur les légumes avec vos mains et sur la plaque.","Cuire au four 25 à 30 minutes.","Pendant ce temps, cuire les pâtes selon les indications sur l''emballage. Égoutter et laisser refroidir complètement.","Dans un grand bol, mélanger les pâtes refroidies, les légumes rôtis, les tomates cerises, le pesto, le fromage de chèvre, les noix de pins et 1 c. à thé de sel. Garnir avec des feuilles de basilic."]'::jsonb, 'salade', 'fromage', array['ete']::text[]) returning id into r;
