  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Chou-fleur rôti et haricots blancs, sauce poivrons cajou', 'photo', null, 'storage:recipe-images/chou-fleur-roti-et-haricots-blancs-sauce-poivrons-cajou.webp', 4, null, '["Préchauffer le four à 425°F. Sur une grande plaque avec un papier parchemin, déposer les fleurets d''un petit chou-fleur et les haricots blancs égouttés (1 canne de 540 ml). Ajouter 3 c. à soupe d''huile d''olive, 2 c. à thé de cumin moulu, 1 c. à thé de paprika fumé, 1 c. à thé de coriandre moulue et ½ c. à thé de sel. Bien mélanger pour enrober et rôtir au four de 15 à 20 minutes, en brassant à mi-cuisson.","Préparer la sauce aux poivrons. Dans un robot culinaire, réduire en purée lisse : 1 canne de poivrons rouges rôtis (340 ml / environ 3 poivrons) égouttés, 4 c. à soupe de beurre de cajou au sel de mer, 1 gousse d''ail hachée, 1 c. à soupe de vinaigre de vin rouge, 1 c. à soupe d''huile d''olive, 1 c. à soupe de pâte de tomates et ¼ c. à thé de sel. Réserver.","Préparer la sauce aux herbes. Dans un bol, mélanger 1 échalote française hachée, 2 c. à soupe de câpres hachés, 1 gousse d''ail hachée, ½ tasse de persil haché, le jus de ½ citron, 3 c. à soupe d''huile d''olive et ¼ c. à thé de sel.","Assembler. Dans une grande assiette ou un plat de service, étendre la sauce aux poivrons. Ajouter le mélange de chou-fleur rôti et de haricots blancs. Garnir généreusement de sauce aux herbes avant de servir."]'::jsonb, 'plaque', 'haricots blancs', array['automne', 'hiver']::text[]) returning id into r;
  insert into recipe_ingredients (recipe_id, position, section, raw, quantity, quantity_max, unit, name, note, optional, ingredient_id) values (r, 0, 'Chou-fleur rôti', '1 petit chou-fleur, les fleurets', 1, null, null, 'chou-fleur', 'les fleurets; petit', false, (select id from ingredients where household_id is null and name = 'Chou-fleur'));
