  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Pâtes façon «pain à l''ail» au pesto et pois chiches', 'photo', null, 'storage:recipe-images/pates-facon-pain-a-l-ail-au-pesto-et-pois-chiches.webp', 4, null, '["Portez une grande casserole d''eau salée à ébullition. Faites cuire les conchiglie rigate selon les indications du paquet, jusqu''à ce qu''elles soient al dente, environ 8 minutes. Égouttez-les, en réservant environ 1/2 tasse d''eau de cuisson des pâtes.","Dans un robot culinaire, mélangez le persil, le basilic, les noix de Grenoble, le parmesan végétal et les gousses d''ail. Pulsez jusqu''à obtenir une consistance grossière. Ajoutez lentement l''huile d''olive tout en mixant, jusqu''à ce que le mélange soit homogène. Goûtez et rectifiez l''assaisonnement avec du sel, si nécessaire. Ajouter le jus de citron, mélanger et réserver.","Préchauffer le four à 400F. Déchirer les tranches de pain directement au-dessus du récipient du robot culinaire. Ajouter l''ail et mélanger jusqu''à ce que les morceaux de pain deviennent de mini croûtons de format inégaux. Transférer la mixture sur une plaque à cuisson allant au four et ajouter l''huile d''olive. Bien incorporer l''huile dans les croûtons et rôtir au four environ 8 minutes jusqu''à l''obtention d''une texture croustillante et d''une couleur dorée. Sortir du four et incorporer le persil – mélanger et réserver.","Chauffer une grande poêle à feu moyen et ajouter un peu d''huile d''olive et les pois chiches. Ajouter les pâtes, remuer légèrement et fermer le feu. Ajouter le pesto et l''eau de cuisson des pâtes et mélanger.","Servir les pâtes dans des assiettes. Saupoudrer de topping croustillant et ajouter du parmesan râpé si désiré."]'::jsonb, 'pâtes', 'pois chiches', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
  insert into recipe_ingredients (recipe_id, position, section, raw, quantity, quantity_max, unit, name, note, optional, ingredient_id) values (r, 0, 'pâtes et les pois chiches', '400 g de conchiglie rigate', 400, null, 'g', 'conchiglie rigate', null, false, (select id from ingredients where household_id is null and name = 'Pâtes courtes'));
