  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Bol de tofu shawarma au houmous', 'photo', null, 'storage:recipe-images/bol-de-tofu-shawarma-au-houmous.webp', 4, null, '["Préparer le tofu. Retirer un maximum d''eau du tofu avec un linge à vaisselle ou un papier essuie-tout. Dans un grand bol, ajouter l''huile d''olive, le jus de citron, le miel/sirop d''érable, l''ail, les épices et le sel. Bien mélanger. Défaire le tofu avec vos doigts pour obtenir des morceaux d''environ 1 pouce. Ajouter les au bol et bien mélanger pour incorporer la marinade au tofu. Couvrir et placer au frigo de 1h à 2h.","Si vous utilisez du houmous du commerce, passez à la prochaine étape. Pour préparer le houmous maison, ajouter tous les ingrédients dans un robot culinaire et pulser pendant quelques minutes jusqu''à l''obtention d''une texture crémeuse. Au besoin, ajouter plus d''eau en fonction de la consistance.","Préparer la salade. Dans un bol, ajouter tous les ingrédients et bien mélanger. Assaisonner généreusement.","Cuire le tofu. Au four : étendre sur une plaque à cuisson avec un papier parchemin et cuire à 425F pendant 15-20 minutes, en retournant à mi-cuisson. Dans une poêle : cuire 2-3 minutes chaque côté des morceaux de tofu. Sur le BBQ : vous pouvez faire des brochettes de tofu et les cuire directement sur le BBQ. Pour ce faire, je recommande de couper le tofu en cubes avant de le mariner et de tout simplement assembler les brochettes. Cuire 2-3 minutes de chaque côté.","Cuire le riz ou le quinoa selon les indications sur l''emballage.","Assembler les bols. Garnir chaque bol de 2 c. à soupe de houmous au fond, le riz/quinoa au milieu, la salade et le tofu cuit par-dessus. Garnir de persil tranché et de fêta émiettée (optionnel)."]'::jsonb, 'bol', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
