  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Cari végétarien et fromage à griller', 'photo', null, 'storage:recipe-images/cari-vegetarien-et-fromage-a-griller.webp', 4, null, '["Dans une casserole antiadhésive à feu moyen, frire les tranches de fromage dans 30 ml (2 c. à soupe) d''huile d''olive pendant 1 minute de chaque côté. Lorsque le fromage est bien doré, retirer de la poêle, couper en cubes, puis réserver.","Dans la même casserole, ajouter le reste de l''huile d''olive, puis faire suer l''ail et l''oignon avec la coriandre, la poudre de cari, le cumin, la poudre de chili, le curcuma, la cannelle et le sel pendant 2 à 3 minutes.","Ajouter les noix de cajou, puis poursuivre la cuisson en remuant pendant 1 à 2 minutes.","Ajouter les tomates, la pâte de tomates, les épinards et les pois chiches, puis poursuivre la cuisson pendant encore 2 à 3 minutes.","Ajouter le lait de coco, mélanger, puis laisser mijoter à feu doux pendant 10 à 12 minutes.","En fin de cuisson, ajouter les cubes de fromage et le miel.","Goûter, puis rectifier l''assaisonnement au besoin.","Déposer le cari sur le riz basmati, puis parsemer de coriandre fraîche. Servir avec les pains naan.","Dans une casserole à feu moyen, griller les grains de riz dans l''huile d''olive avec le sel en remuant pour bien enrober le riz d''huile.","Lorsque le riz commence à dégager une odeur de noisette, ajouter l''eau, puis couvrir.","Porter à ébullition, puis baisser le feu au minimum. Cuire pendant environ 10 à 15 minutes sans toucher, ou jusqu''à ce que le riz ait absorbé l''eau.","Lorsqu''il est cuit, toujours sans toucher, retirer la casserole du feu, puis laisser reposer avec le couvercle pendant au moins 5 minutes avant de servir."]'::jsonb, 'mijoté', 'fromage', array['automne', 'hiver']::text[]) returning id into r;
