  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Plaque de pois chiches et halloumi, yogourt au sumac', 'photo', null, 'storage:recipe-images/plaque-de-pois-chiches-et-halloumi-yogourt-au-sumac.webp', 4, null, '["Placer la grille au centre du four et préchauffer à 425°F. Recouvrir une plaque de cuisson de papier parchemin ou pellicule de silicone.","Ajouter le halloumi en cubes, la patate douce en cubes, le poivron rouge en cubes, l''oignon haché, les pois chiches égouttés et rincés, 3 c. à soupe d''huile d''olive, 1 c. à soupe de miel, 2 gousses d''ail hachées, 2 c. à thé de cumin, 2 c. à thé de coriandre moulue, 2 c. à thé de paprika, ½ c. à thé de cannelle, ½ c. à thé de gingembre moulu, ½ c. à thé de curcuma et ¾ c. à thé de sel. Bien mélanger avec vos mains et répartir uniformément sur la plaque.","Cuire au four pendant environ 30-35 minutes, en remuant à mi-cuisson, jusqu''à ce que le halloumi soit ramolli et que les légumes soient cuits.","Pendant ce temps, dans un bol, mélanger 1 tasse de yogourt grec, le jus et le zeste de ½ citron, 1 gousse d''ail hachée, 1 c. à thé de sumac et ½ c. à thé de sel. Bien mélanger et réserver.","Servir le mélange de pois chiches et de halloumi avec de la coriandre fraîche, la sauce et un accompagnement au choix."]'::jsonb, 'plaque', 'pois chiches', array['automne']::text[]) returning id into r;
