  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Cari végétarien au chou-fleur et patates douces', 'photo', null, 'storage:recipe-images/cari-vegetarien-au-chou-fleur-et-patates-douces.webp', 6, null, '["Dans un petit bol, bien mélanger tous les ingrédients de la pâte de cari. Réserver.","Dans un grand faitout ou un chaudron de type Creuset, sur feu moyen, faire revenir les oignons dans l''huile jusqu''à ce qu''ils soient tendres.","Ajouter le chou-fleur, les patates douces et la pâte de cari et mélanger jusqu''à ce que les légumes soient bien enrobés. Poursuivre la cuisson 2 minutes en mélangeant bien.","Ajouter le bouillon de légumes, le lait de coco et la pâte de tomate et porter à ébullition.","Poursuivre la cuisson à feu très doux, à couvert, 15 minutes.","Ajouter le jus de lime. Rectifier l''assaisonnement, ajouter les petits pois et les noix de cajou et cuire encore 2 minutes. Servir avec la coriandre, les graines de pomme grenade et le piment chili doux."]'::jsonb, 'mijoté', 'végé', array['automne', 'hiver']::text[]) returning id into r;
