  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Bol de tofu Satay', 'photo', null, 'storage:recipe-images/bol-de-tofu-satay.webp', 2, null, '["Préchauffer le four à 400F et placer la grille au milieu.","Dans un grand bol, combiner 2 c. à soupe de sauce soya, 2 c. à soupe de vinaigre de riz et 1 c. à soupe de sirop d''érable. Défaire le bloc de tofu avec vos mains pour obtenir des morceaux d''environ 1 pouce et bien répartir la marinade sur le tofu.","Transférer sur une plaque à cuisson et laisser un peu d''espace entre chaque morceau de tofu. Cuire au four pendant 15-17 minutes. Au besoin, finir la cuisson à broil pour obtenir des morceaux plus grillés.","Préparer la sauce aux arachides en combinant tous les ingrédients ensemble. ¼ de tasse de beurre d''arachide naturel, 3 c. à soupe de sauce soya, 1 c. à soupe de sirop d''érable, 2 c. à soupe de vinaigre de riz, 3 c. à soupe d''eau, 1 c. à thé de sriracha et le gingembre râpé (un morceau de ½ pouce).","Préparer la salade: Trancher le chou finement, couper les concombres en biseaux, trancher finement les oignons verts et trancher grossièrement la coriandre. Mélanger les légumes ensemble directement sur la planche à découper.","Réchauffer le riz.","Assembler les bols avec le riz, le tofu cuit et la salade. Garnir avec la sauce aux arachides. Décorer avec des oignons marinés et des arachides hachées (optionnel)."]'::jsonb, 'bol', 'tofu', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
