  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Bol burrito végé chili lime', 'photo', null, 'storage:recipe-images/bol-burrito-vege-chili-lime.webp', 4, null, '["Préchauffer le four à 425˚F et placer la grille au centre.","Faire bouillir de l''eau dans une bouilloire. Dans un pot Mason, ajouter 1 oignon rouge tranché, ⅓ de tasse d''eau bouillante, ⅓ de tasse de vinaigre de cidre de pommes, 2 c. à soupe de sucre blanc et ½ c. à thé de sel, mélanger puis laisser reposer pour faire mariner.","Cuire 1 ¾ tasse de riz blanc sec selon les indications sur l''emballage.","Sur une plaque tapissée de papier parchemin, déposer 2 patates douces moyennes en dés, arroser avec 3 c. à soupe d''huile d''olive, 1 c. à thé de paprika fumé, ½ c. à thé de poudre d''ail et ¼ c. à thé de sel et bien mélanger. Cuire au four 15–17 minutes, en mélangeant à mi-cuisson.","Pour la salsa, mettre dans un bol 1 contenant (551 ml) de tomates cerises coupées en deux, 3 oignons verts tranchés, 1 gousse d''ail hachée et ¼ de tasse de fêta émiettée, ajouter un filet d''huile d''olive et mélanger.","Dans une poêle, réchauffer 2 cannes (398 ml chacune) de haricots noirs sauce burrito chili lime de Clark environ 5 minutes, en remuant.","Pour l''assemblage, répartir le riz dans les bols, garnir avec les haricots noirs réchauffés et les patates douces rôties, ajouter la salsa de tomates, un peu de crème sûre, les oignons marinés et terminer avec de la sauce piquante au goût."]'::jsonb, 'bol', 'haricots noirs', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
