  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Roasted Vegetable Salad with Crispy Chickpeas', 'photo', null, 'storage:recipe-images/roasted-vegetable-salad-with-crispy-chickpeas.webp', 4, null, '["Line two baking trays and preheat the oven to 425°F (220°C).","Add the chickpeas to one of the baking trays. Drizzle over the oil and the burrito spice seasoning. Toss to coat.","To the second baking tray, add the potatoes, carrots, unpeeled garlic, oil, and burrito seasoning. Toss to coat. Roast both trays for 20 minutes.","Meanwhile, place the frozen peas in a medium bowl and cover them with plenty of boiling water. Let sit for 10 minutes.","Remove the trays from the oven. Add the onion wedges to the veggie tray and stir. Return the trays to swapped positions in the oven, and roast for an additional 15 - 25 minutes or until cooked to your liking.","Drain the peas and mash with a fork, then add the yogurt, salt, and pepper to the peas and mix.","When the roasted garlic is cool enough to handle, peel and mash the cloves with a fork. Add this to the yogurt sauce. Mix. For a smoother consistency, blend the yogurt sauce with an immersion blender, although this is optional. Taste test and add more salt if desired.","To assemble, divide the spinach between bowls. Top with the roasted veggies and chickpeas. Add a dollop of the pea yogurt sauce before digging in. Enjoy!"]'::jsonb, 'salade', 'pois chiches', array['automne']::text[]) returning id into r;
