  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Cari de tempeh', 'photo', null, 'storage:recipe-images/cari-de-tempeh.webp', 4, null, '["Dans une poêle, à feu vif, faire revenir le poivron rouge et le tempeh dans l''huile 7 minutes à feu vif.","Ajouter les courgettes, les échalotes françaises, l''ail et le gingembre et poursuivre la cuisson 3 minutes.","Ajouter le reste des ingrédients, porter à ébullition, réduire le feu et laisser mijoter 15 minutes."]'::jsonb, 'mijoté', 'tempeh', array['printemps', 'ete', 'automne', 'hiver']::text[]) returning id into r;
