  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Vegan Tuna', 'photo', null, 'storage:recipe-images/vegan-tuna.webp', 4, null, '["Add the chickpeas to a mixing bowl and mash them with a fork.","Add in vegan mayonnaise, finely chopped nori, finely chopped red onion, lemon juice, finely chopped capers, garlic powder, nutritional yeast, tamari, dijon mustard, white vinegar and salt and pepper.","Taste test and add more salt and pepper if needed.","Mix in and you''re ready to serve!"]'::jsonb, 'sandwich', 'pois chiches', array['printemps', 'ete']::text[]) returning id into r;
