  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Salade de couscous perlé aux légumes rôtis et tomates séchées', 'photo', null, 'storage:recipe-images/salade-de-couscous-perle-aux-legumes-rotis-et-tomates-sechee.webp', 4, null, '["Préchauffer le four à 425°F (220°C). Sur une grande plaque de cuisson tapissée de papier parchemin, déposer 1 grosse courgette (environ 2 tasses) coupée en dés, 2 poivrons rouges (environ 1 ½ tasse) coupés en dés, 1 oignon rouge moyen coupé en dés et 1 boîte (540 ml) de pois chiches, égouttés et rincés.","Ajouter 3 c. à soupe d''huile d''olive, 1 c. à soupe de paprika fumé, 2 c. à thé d''origan séché, 2 c. à thé de cumin moulu, 1 c. à thé de poudre d''ail, 1 c. à thé de sel et du poivre fraîchement moulu.","Bien mélanger, étaler en une seule couche et rôtir au four de 25 à 30 minutes, jusqu''à ce que les légumes soient tendres et légèrement dorés.","Cuire le couscous perlé selon les indications sur l''emballage. Une fois cuit, incorporer ½ tasse de raisins secs pendant que le couscous est encore chaud pour les attendrir. Réserver.","Préparer la vinaigrette.Dans un mélangeur ou à l''aide d''un pied mélangeur, réduire en purée ½ tasse de tomates séchées dans l''huile (égouttées), ⅓ tasse d''huile d''olive, le zeste et le jus de 1 citron, 1 gousse d''ail, 3 c. à soupe de vinaigre balsamique blanc, 1 c. à soupe de moutarde de Dijon, 1 c. à soupe de miel, 1 c. à thé d''origan séché, 1 c. à thé de sel et du poivre au goût. Au besoin, ajouter 2 à 3 c. à soupe d''eau en fonction de la consistance.","Assembler la salade. Dans un grand bol, mélanger le couscous, les légumes rôtis, 100 g (½ tasse) de feta en cubes, ½ tasse d''herbes fraîches hachées et noix au choix (facultatif). Verser la vinaigrette par-dessus et bien mélanger pour enrober.","Servir tiède, à température ambiante ou froid. La salade se conserve 3 jours au frigo dans un contenant hermétique."]'::jsonb, 'salade', 'pois chiches', array['ete', 'automne']::text[]) returning id into r;
  insert into recipe_ingredients (recipe_id, position, section, raw, quantity, quantity_max, unit, name, note, optional, ingredient_id) values (r, 0, 'Légumes rôtis', '1-2 courgettes, coupée(s) en dés (environ 2 tasses)', 1, 2, null, 'courgettes', 'coupée en dés; environ 2 tasses', false, (select id from ingredients where household_id is null and name = 'Courgette'));
