  insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) values (h, 'Cari rouge à la citrouille, pois chiches et épinards', 'photo', null, 'storage:recipe-images/cari-rouge-a-la-citrouille-pois-chiches-et-epinards.webp', 4, null, '["Dans un grand chaudron à feu moyen, faire revenir l''oignon dans l''huile de coco ou le beurre.","Ajouter ensuite le gingembre, l''ail et la pâte de cari rouge. Cuire pour environ 1 minute.","Ajouter ensuite le lait de coco et bien mélanger. Ajouter la citrouille en cubes, le miel, la sauce soya et le jus de lime. Porter à ébullition et réduire le feu.","Laisser mijoter pour environ 10-12 minutes, jusqu''à ce que la citrouille soit tendre mais pas trop cuite.","Ajouter ensuite les pois chiches et les épinards. Cuire pour 1-2 minutes.","Ajuster l''assaisonnement et servir avec du riz ou des nouilles de riz. Garnir avec des arachides et de la coriandre."]'::jsonb, 'mijoté', 'pois chiches', array['automne']::text[]) returning id into r;
